const max_request_bytes: usize = 4 * 1024 * 1024;

const HttpRequest = struct {
    buffer: []u8,
    method: []const u8,
    path: []const u8,
    body: []const u8,

    pub fn deinit(self: *HttpRequest, allocator: std.mem.Allocator) void {
        allocator.free(self.buffer);
    }
};

