            return error.UnexpectedEndOfStream;
        }

        const old_len = buffer.len;
        buffer = try allocator.realloc(buffer, old_len + bytes_read);
        @memcpy(buffer[old_len .. old_len + bytes_read], temp[0..bytes_read]);

        if (buffer.len > max_request_bytes) return error.RequestTooLarge;

        if (header_end_opt == null) {
            if (std.mem.indexOf(u8, buffer, "\r\n\r\n")) |header_end| {
                header_end_opt = header_end;
                const content_length = try parseContentLength(buffer[0..header_end]);
                total_len_opt = header_end + 4 + content_length;
            }
