    const names = [_][]const u8{
        "ANTHROPIC_API_KEY",
        "PROVIDER_KEY",
        "BYTEZ_PROVIDER_KEY",
    };

    for (names) |name| {
        const value = std.process.getEnvVarOwned(allocator, name) catch |err| switch (err) {
            error.EnvironmentVariableNotFound => continue,
            else => return err,
        };
        return value;
    }

    return null;
}

fn buildBytezPayload(allocator: std.mem.Allocator, messages_value: std.json.Value) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();

    try out.writer.writeAll("{\"messages\":");
    try std.json.Stringify.value(messages_value, .{}, &out.writer);
    try out.writer.writeAll(",\"stream\":false,\"params\":{\"max_tokens\":128000,\"temperature\":1}}");

    return try allocator.dupe(u8, out.written());
}

fn buildErrorJson(allocator: std.mem.Allocator, message: []const u8) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();

    try out.writer.writeAll("{\"error\":");
    try writeJsonString(&out.writer, message);
    try out.writer.writeAll(",\"output\":null}");

    return try allocator.dupe(u8, out.written());
}

fn writeResponse(stream: std.net.Stream, status_line: []const u8, content_type: []const u8, body: []const u8) !void {
    var header_buffer: [512]u8 = undefined;
    const header = try std.fmt.bufPrint(&header_buffer, "HTTP/1.1 {s}\r\nContent-Type: {s}\r\nContent-Length: {d}\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n", .{ status_line, content_type, body.len });
    try stream.writeAll(header);
    try stream.writeAll(body);
}

fn writeJsonString(writer: *std.Io.Writer, value: []const u8) !void {
    const hex = "0123456789abcdef";

    try writer.writeByte('"');
    for (value) |byte| {
        switch (byte) {
            '"' => try writer.writeAll("\\\""),
            '\\' => try writer.writeAll("\\\\"),
            '\n' => try writer.writeAll("\\n"),
            '\r' => try writer.writeAll("\\r"),
            '\t' => try writer.writeAll("\\t"),
            0x08 => try writer.writeAll("\\b"),
            0x0c => try writer.writeAll("\\f"),
            else => {
                if (byte < 0x20) {
                    try writer.writeAll("\\u00");
                    try writer.writeByte(hex[@as(usize, (byte >> 4) & 0x0f)]);
                    try writer.writeByte(hex[@as(usize, byte & 0x0f)]);
                } else {
                    try writer.writeByte(byte);
                }
            },
        }
    }
    try writer.writeByte('"');
}

