const ConnectionQueue = struct {
    mutex: std.Thread.Mutex = .{},
    cond: std.Thread.Condition = .{},
    buffer: [queue_capacity]std.net.Server.Connection = undefined,
    head: usize = 0,
    tail: usize = 0,
    len: usize = 0,

    fn push(self: *ConnectionQueue, conn: std.net.Server.Connection) bool {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.len == self.buffer.len) return false;
        self.buffer[self.tail] = conn;
        self.tail = (self.tail + 1) % self.buffer.len;
        self.len += 1;
        self.cond.signal();
        return true;
    }

    fn pop(self: *ConnectionQueue) std.net.Server.Connection {
        self.mutex.lock();
        defer self.mutex.unlock();
        while (self.len == 0) {
            self.cond.wait(&self.mutex);
        }
        const conn = self.buffer[self.head];
        self.head = (self.head + 1) % self.buffer.len;
        self.len -= 1;
