fn stripQuery(path: []const u8) []const u8 {
    if (std.mem.indexOfScalar(u8, path, '?')) |idx| return path[0..idx];
    return path;
}

fn readHttpRequest(allocator: std.mem.Allocator, stream: std.net.Stream) !HttpRequest {
    var capacity = initial_buffer_size;
    var buffer = try allocator.alloc(u8, capacity);
    errdefer allocator.free(buffer);
    var used: usize = 0;
    var temp: [4096]u8 = undefined;
    var header_end_opt: ?usize = null;
    var total_len_opt: ?usize = null;

    while (true) {
        const bytes_read = try stream.read(&temp);
        if (bytes_read == 0) {
            if (total_len_opt) |total_len| {
                if (used >= total_len) break;
            }
            return error.UnexpectedEndOfStream;
        }

        if (used + bytes_read > capacity) {
            capacity = @max(capacity * 2, used + bytes_read);
            buffer = try allocator.realloc(buffer, capacity);
        }

        @memcpy(buffer[used .. used + bytes_read], temp[0..bytes_read]);
        used += bytes_read;

        if (header_end_opt == null and used > max_header_bytes) return error.RequestTooLarge;
        if (used > max_request_bytes) return error.RequestTooLarge;

        if (header_end_opt == null) {
            if (std.mem.indexOf(u8, buffer[0..used], "\r\n\r\n")) |header_end| {
                if (header_end > max_header_bytes) return error.RequestTooLarge;
                header_end_opt = header_end;
                const content_length = try parseContentLength(buffer[0..header_end]);
                const with_separator = std.math.add(usize, header_end, 4) catch return error.BadRequest;
                const body_end = std.math.add(usize, with_separator, content_length) catch return error.BadRequest;
                if (body_end > max_request_bytes) return error.RequestTooLarge;
                total_len_opt = body_end;
            }
        }

        if (total_len_opt) |total_len| {
            if (used == total_len) break;
            if (used > total_len) return error.BadRequest;
        }
    }

    const header_end = header_end_opt orelse return error.BadRequest;
    const total_len = total_len_opt orelse return error.BadRequest;
    if (used != total_len) return error.BadRequest;

    const request_line_end = std.mem.indexOf(u8, buffer[0..header_end], "\r\n") orelse return error.BadRequest;
    const request_line = buffer[0..request_line_end];
    if (request_line.len == 0) return error.BadRequest;
    for (request_line) |c| {
        if (c == 0) return error.BadRequest;
    }

    var parts = std.mem.splitScalar(u8, request_line, ' ');
    const method = parts.next() orelse return error.BadRequest;
    const path_raw = parts.next() orelse return error.BadRequest;
    const version = parts.next() orelse return error.BadRequest;
    if (parts.next() != null) return error.BadRequest;

    if (method.len == 0 or path_raw.len == 0 or version.len == 0) return error.BadRequest;
    if (!std.mem.eql(u8, version, "HTTP/1.0") and !std.mem.eql(u8, version, "HTTP/1.1")) return error.BadRequest;
    if (!isValidHttpMethod(method)) return error.BadRequest;
    if (!isValidPath(path_raw)) return error.BadRequest;
    try validateHeaders(buffer[0..header_end], version);

    return .{
        .buffer = buffer[0..used],
        .method = method,
        .path = path_raw,
        .body = buffer[header_end + 4 .. total_len],
    };
}

fn isValidHttpMethod(method: []const u8) bool {
    const valid = [_][]const u8{ "GET", "HEAD", "POST", "PUT", "DELETE", "PATCH", "OPTIONS", "TRACE", "CONNECT" };
    for (valid) |candidate| {
        if (std.mem.eql(u8, method, candidate)) return true;
    }
    return false;
}

fn isValidPath(path: []const u8) bool {
    if (path.len == 0) return false;
    if (path[0] != '/') return false;
    for (path) |c| {
        if (c == 0) return false;
        if (c < 0x20) return false;
    }
    return true;
}

fn validateHeaders(headers: []const u8, version: []const u8) !void {
    var lines = std.mem.splitSequence(u8, headers, "\r\n");
    _ = lines.next();
    var host_count: usize = 0;

    while (lines.next()) |line| {
        if (line.len == 0) continue;
        for (line) |c| {
            if (c == 0) return error.BadRequest;
        }
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.BadRequest;
        const name = std.mem.trim(u8, line[0..colon], " \t");
        const value = std.mem.trim(u8, line[colon + 1 ..], " \t");
        if (name.len == 0) return error.BadRequest;
        if (std.mem.indexOfScalar(u8, name, ' ') != null) return error.BadRequest;
        if (std.mem.indexOfScalar(u8, name, '\t') != null) return error.BadRequest;
        if (std.ascii.eqlIgnoreCase(name, "Host")) {
            if (value.len == 0) return error.BadRequest;
            host_count += 1;
        }
        if (std.ascii.eqlIgnoreCase(name, "Transfer-Encoding")) return error.BadRequest;
    }

    if (std.mem.eql(u8, version, "HTTP/1.1") and host_count != 1) return error.BadRequest;
}

fn parseContentLength(headers: []const u8) !usize {
    var lines = std.mem.splitSequence(u8, headers, "\r\n");
    _ = lines.next();
    var found_count: usize = 0;
    var found_value: usize = 0;

    while (lines.next()) |line| {
        if (line.len == 0) continue;
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.BadRequest;
        const name = std.mem.trim(u8, line[0..colon], " \t");
        const raw_value = std.mem.trim(u8, line[colon + 1 ..], " \t");
        if (std.ascii.eqlIgnoreCase(name, "Content-Length")) {
            if (raw_value.len == 0) return error.BadRequest;
            for (raw_value) |c| {
                if (c < '0' or c > '9') return error.BadRequest;
            }
            const parsed_value = try std.fmt.parseInt(usize, raw_value, 10);
            if (found_count > 0 and parsed_value != found_value) return error.BadRequest;
            found_value = parsed_value;
            found_count += 1;
        }
        if (std.ascii.eqlIgnoreCase(name, "Transfer-Encoding")) return error.BadRequest;
    }

    return found_value;
}

