fn looksLikeJson(bytes: []const u8) bool {
    var i: usize = 0;
    while (i < bytes.len) : (i += 1) {
        const c = bytes[i];
        if (c == ' ' or c == '\t' or c == '\r' or c == '\n') continue;
        return c == '{' or c == '[';
    }
    return false;
}

fn getProviderKey(allocator: std.mem.Allocator) !?[]u8 {
    const names = [_][]const u8{
        "BYTEZ_PROVIDER_KEY",
        "ANTHROPIC_API_KEY",
        "PROVIDER_KEY",
    };

    for (names) |name| {
        const value = std.process.getEnvVarOwned(allocator, name) catch |err| switch (err) {
            error.EnvironmentVariableNotFound => continue,
            else => return err,
        };
        if (std.mem.trim(u8, value, " \t\r\n").len == 0) {
            allocator.free(value);
            continue;
        }
        return value;
    }

    return null;
}

fn buildBytezPayload(allocator: std.mem.Allocator, messages_value: std.json.Value) ![]u8 {
    var out = std.ArrayList(u8).init(allocator);
    defer out.deinit();

    const writer = out.writer();
    try writer.writeAll("{\"messages\":");
    try std.json.stringify(messages_value, .{}, writer);
    try writer.writeAll(",\"stream\":false,\"params\":{\"max_tokens\":8096,\"temperature\":1}}");

    return out.toOwnedSlice();
}

fn buildErrorJson(allocator: std.mem.Allocator, message: []const u8) ![]u8 {
    var out = std.ArrayList(u8).init(allocator);
    defer out.deinit();

    const writer = out.writer();
    try writer.writeAll("{\"error\":");
    try writeJsonString(writer, message);
    try writer.writeAll(",\"output\":null}");

    return out.toOwnedSlice();
}

fn writeStaticResponse(stream: std.net.Stream, status_line: []const u8, content_type: []const u8, body: []const u8) !void {
    var header_buffer: [response_header_buffer_size]u8 = undefined;
    const header = try std.fmt.bufPrint(&header_buffer, "HTTP/1.1 {s}\r\nContent-Type: {s}\r\nContent-Length: {d}\r\nConnection: close\r\nX-Content-Type-Options: nosniff\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, HEAD, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\n\r\n", .{ status_line, content_type, body.len });
    try stream.writeAll(header);
    try stream.writeAll(body);
}

